package org.beyondlight;
import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.io.*;import java.util.concurrent.*;
/** Local raw-preserving numeric dataset repository with preview-then-commit imports. */
public final class DataRepository {
 public record Dataset(String id,String filename,String format,String source,String author,String year,String doi,String equationId,String variables,String units,String conditions,String uncertainty,String raw, int rows,String status,String importedAt){}
 private final Path path;private final Map<String,Dataset>pending=new ConcurrentHashMap<>();
 public DataRepository(Path p){path=p;}
 public synchronized List<Dataset> all(){try{List<Dataset>a=new ArrayList<>();if(Files.exists(path))for(String l:Files.readAllLines(path))if(!l.isBlank())a.add(from(Json.map(Json.parse(l))));return a;}catch(IOException e){throw new IllegalStateException("dataset store read failed");}}
 public Dataset preview(String filename,String format,String raw,Map<String,String>meta){if(filename.length()>256||raw.isBlank()||filename.contains("/")||filename.contains("\\")||filename.chars().anyMatch(c->c<32))throw new IllegalArgumentException("safe filename and nonempty dataset are required");if(raw.length()>10_000_000)throw new IllegalArgumentException("dataset exceeds 10 MB limit");String f=format.toLowerCase(Locale.ROOT);List<String>vars;List<List<String>>rows;String status="UNVERIFIED — IMPORTED USER DATA";if(f.equals("csv")){List<List<String>>t=csv(raw);if(t.size()<2)throw new IllegalArgumentException("CSV needs a header and at least one row");vars=t.get(0);rows=t.subList(1,t.size());}else if(f.equals("json")){Map<String,Object>o=Json.map(Json.parse(raw));vars=strings(o.get("variables"));rows=new ArrayList<>();Object ro=o.get("rows");if(!(ro instanceof List<?>rl))throw new IllegalArgumentException("JSON dataset requires rows array");for(Object row:rl)rows.add(strings(row));}else throw new IllegalArgumentException("format must be CSV or JSON");if(vars.isEmpty()||vars.size()>100)throw new IllegalArgumentException("dataset must have 1..100 variables");if(rows.isEmpty()||rows.size()>100_000)throw new IllegalArgumentException("dataset must have 1..100,000 data rows");Set<String>unique=new HashSet<>();for(String v:vars)if(v.isBlank()||!unique.add(v))throw new IllegalArgumentException("column names must be nonempty and unique");int duplicates=0;Set<List<String>>seen=new HashSet<>();for(int i=0;i<rows.size();i++){List<String>r=rows.get(i);if(r.size()!=vars.size())throw new IllegalArgumentException("row "+(i+2)+" has "+r.size()+" values; expected "+vars.size());for(int c=0;c<r.size();c++){if(r.get(c).isBlank())throw new IllegalArgumentException("missing value at row "+(i+2)+", column "+vars.get(c));try{double v=Double.parseDouble(r.get(c));if(!Double.isFinite(v))throw new NumberFormatException();}catch(NumberFormatException e){throw new IllegalArgumentException("non-numeric value at row "+(i+2)+", column "+vars.get(c));}}if(!seen.add(List.copyOf(r)))duplicates++;}if(duplicates>0)status+="; duplicate rows="+duplicates;String unit=meta.getOrDefault("units","");validateUnits(vars,unit);Dataset d=new Dataset(UUID.randomUUID().toString(),filename,f,meta.getOrDefault("source",""),meta.getOrDefault("author",""),meta.getOrDefault("year",""),meta.getOrDefault("doi",""),meta.getOrDefault("equationId",""),String.join(",",vars),unit,meta.getOrDefault("conditions",""),meta.getOrDefault("uncertainty",""),raw,rows.size(),status,Instant.now().toString());pending.put(d.id,d);return d;}
 public synchronized Dataset commit(String id){Dataset d=pending.remove(id);if(d==null)throw new IllegalArgumentException("preview not found or already committed");List<Dataset>a=all();if(a.stream().anyMatch(x->x.filename.equals(d.filename)&&x.raw.equals(d.raw)))throw new IllegalArgumentException("duplicate dataset content already stored");a.add(d);write(a);return d;}
 public synchronized void remove(String id){List<Dataset>a=all();if(!a.removeIf(d->d.id.equals(id)))throw new IllegalArgumentException("dataset not found");write(a);}
 public Dataset get(String id){return all().stream().filter(d->d.id.equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("dataset not found"));}
 public List<Dataset>search(String q){String t=q.toLowerCase();return all().stream().filter(d->(d.filename+d.source+d.author+d.variables+d.conditions).toLowerCase().contains(t)).toList();}
 public List<List<String>>previewRecords(Dataset d){if(d.format.equals("csv")){List<List<String>>t=csv(d.raw);return t.subList(0,Math.min(t.size(),7));}Map<String,Object>o=Json.map(Json.parse(d.raw));List<List<String>>t=new ArrayList<>();t.add(strings(o.get("variables")));for(Object row:(List<?>)o.get("rows"))t.add(strings(row));return t.subList(0,Math.min(t.size(),7));}
 public String exportCsv(String id){Dataset d=get(id);return d.raw;}
 public synchronized Dataset updateMetadata(String id,Map<String,String>m){List<Dataset>a=all();Dataset old=a.stream().filter(d->d.id.equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("dataset not found"));Dataset n=new Dataset(old.id,old.filename,old.format,m.getOrDefault("source",old.source),m.getOrDefault("author",old.author),m.getOrDefault("year",old.year),m.getOrDefault("doi",old.doi),m.getOrDefault("equationId",old.equationId),old.variables,old.units,m.getOrDefault("conditions",old.conditions),m.getOrDefault("uncertainty",old.uncertainty),old.raw,old.rows,old.status,old.importedAt);a.replaceAll(x->x.id.equals(id)?n:x);write(a);return n;}
 private void write(List<Dataset>a){try{Files.createDirectories(path.getParent());StringBuilder b=new StringBuilder();for(Dataset d:a)b.append(Json.stringify(asMap(d))).append('\n');Files.writeString(path,b,StandardCharsets.UTF_8);}catch(IOException e){throw new IllegalStateException("dataset store write failed");}}
 private static Map<String,Object>asMap(Dataset d){Map<String,Object>m=new LinkedHashMap<>();m.put("id",d.id);m.put("filename",d.filename);m.put("format",d.format);m.put("source",d.source);m.put("author",d.author);m.put("year",d.year);m.put("doi",d.doi);m.put("equationId",d.equationId);m.put("variables",d.variables);m.put("units",d.units);m.put("conditions",d.conditions);m.put("uncertainty",d.uncertainty);m.put("raw",d.raw);m.put("rows",d.rows);m.put("status",d.status);m.put("importedAt",d.importedAt);return m;}
 private static Dataset from(Map<String,Object>m){return new Dataset(s(m,"id"),s(m,"filename"),s(m,"format"),s(m,"source"),s(m,"author"),s(m,"year"),s(m,"doi"),s(m,"equationId"),s(m,"variables"),s(m,"units"),s(m,"conditions"),s(m,"uncertainty"),s(m,"raw"),(int)((Number)m.get("rows")).doubleValue(),s(m,"status"),s(m,"importedAt"));}private static String s(Map<String,Object>m,String k){return Objects.toString(m.getOrDefault(k,""),"");}
 private static List<String>strings(Object o){if(!(o instanceof List<?>l))throw new IllegalArgumentException("array expected");return l.stream().map(String::valueOf).toList();}
 public static List<List<String>>csv(String s){List<List<String>>out=new ArrayList<>();List<String>row=new ArrayList<>();StringBuilder cell=new StringBuilder();boolean quoted=false;for(int i=0;i<s.length();i++){char c=s.charAt(i);if(quoted){if(c=='"'&&i+1<s.length()&&s.charAt(i+1)=='"'){cell.append('"');i++;}else if(c=='"')quoted=false;else cell.append(c);}else if(c=='"'){if(cell.length()!=0)throw new IllegalArgumentException("quote must begin at cell start");quoted=true;}else if(c==','){row.add(cell.toString().trim());cell.setLength(0);}else if(c=='\n'||c=='\r'){if(c=='\r'&&i+1<s.length()&&s.charAt(i+1)=='\n')i++;row.add(cell.toString().trim());cell.setLength(0);out.add(row);row=new ArrayList<>();}else cell.append(c);if(out.size()>100001)throw new IllegalArgumentException("CSV exceeds 100,000 rows");}if(quoted)throw new IllegalArgumentException("unterminated quoted cell");if(cell.length()>0||!row.isEmpty()){row.add(cell.toString().trim());out.add(row);}return out;}
 private static void validateUnits(List<String>v,String units){if(units.isBlank())return;for(String pair:units.split(",")){String[]a=pair.trim().split(":",2);if(a.length!=2)throw new IllegalArgumentException("units format is variable:unit comma list");if(!v.contains(a[0]))throw new IllegalArgumentException("unit provided for unknown variable "+a[0]);if(!Set.of("1","m","km","cm","s","min","h","kg","g","N","kN","J","MJ","W","kW","Pa","K","A","m/s","m/s2","kg/m3").contains(a[1]))throw new IllegalArgumentException("unsupported unit "+a[1]+"; raw data retained in source units, no implicit conversion");}}
}
